 const base=isSupplier?((state.suppliers&&state.suppliers.length)?state.suppliers:(master.suppliers||[]).map((x,i)=>typeof x==='string'?{id:'SUPP-'+String(i+1).padStart(3,'0'),name:x}:x)):(type==='products'?(master.products||[]):(master.recipes||[]).filter(r=>isPrep?masterRecipeIsPrep(r):!masterRecipeIsPrep(r)));
 const hidden=new Set(state.masterHidden[isPrep?'recipes':type]||[]);
 const overrides=state.masterOverrides[isPrep?'recipes':type]||{};
 return base.filter(x=>!hidden.has(String(x.id))).map(x=>({...x,...(overrides[x.id]||{})}));
