function lrxNotifications(){const out=[];const pct=Number(state.settings?.priceIncreaseAlertPct||10);if(state.settings?.priceIncreaseAlertEnabled!==false){(state.purchasePriceHistory||[]).slice().reverse().forEach(h=>{if(Number(h.increasePct||0)>=pct)out.push({type:'PRECIO',title:'Aumento de costo',detail:`${h.product||'Producto'} · +${Number(h.increasePct||0).toFixed(1)}%`,date:h.date||h.createdAt})})}(state.permits||[]).forEach(r=>{if(r.expiryDate){const days=Math.ceil((new Date(r.expiryDate+'T23:59:59').getTime()-Date.now())/86400000);if(days<=30)out.push({type:'VENCIMIENTO',title:days<0?'Documento vencido':'Vencimiento próximo',detail:`${r.name||'Documento'} · ${days<0?'vencido':days+' días'}`,date:r.expiryDate})}});(state.nasRecords||[]).forEach(r=>{if(r.expiryDate){const days=Math.ceil((new Date(r.expiryDate+'T23:59:59').getTime()-Date.now())/86400000);const alertDays=Math.max(1,Number(r.alertDays||30));if(days<=alertDays)out.push({type:'VENCIMIENTO',title:days<0?'Documento NAS vencido':'Vencimiento NAS próximo',detail:`${r.name||'Documento'} · ${days<0?'vencido':days+' días'}`,date:r.expiryDate})}});(state.inventory||[]).forEach(i=>{const min=Number(i.minQty||0);if(min>0&&Number(i.qty||0)<=min)out.push({type:'INVENTARIO',title:'Stock bajo',detail:`${i.product||'Producto'} · ${Number(i.qty||0)} ${i.unit||''}`,date:now()})});const lotAlertDays=Math.max(1,Number(state.settings?.inventoryExpiryAlertDays||20));inv208Lots().forEach(l=>{if(Number(l.qty||0)<=0)return;const expiry=inv208Expiry(l),days=inv208Days(expiry);if(days!==null&&days<=lotAlertDays)out.push({type:'VENCIMIENTO',title:days<0?'Producto vencido':days===0?'Producto vence hoy':'Producto próximo a vencer',detail:`${l.product||'Producto'} · Lote ${l.lot||l.id} · ${days<0?'vencido hace '+Math.abs(days)+' días':days===0?'vence hoy':'vence en '+days+' días'} · ${Number(l.qty||0)} ${l.unit||''}`,date:expiry||''})});return out.slice(0,40)}
