function requireSecure(){if(!secureAccess()){toast('Módulo restringido: solo socios/inversionistas y personal administrativo-financiero autorizado');return false}return true}
function exportValue(v){if(v===null||v===undefined)return '';if(v instanceof Date)return v.toISOString();if(typeof v==='object'){try{return JSON.stringify(v)}catch(e){return String(v)}}return String(v)}
function csvEscape(v){return JSON.stringify(exportValue(v))}
function exportRows(rows,name){if(!Array.isArray(rows)||!rows.length)return toast('No hay datos para exportar');const safe=rows.filter(r=>r&&typeof r==='object').map(({password,externalPassword,...row})=>row);if(!safe.length)return toast('No hay datos válidos para exportar');const headers=[...new Set(safe.flatMap(r=>Object.keys(r)))];const csv='\ufeff'+[headers.map(csvEscape).join(','),...safe.map(r=>headers.map(h=>csvEscape(r[h])).join(','))].join('\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${name}_${new Date().toISOString().slice(0,10)}.csv`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
