 const inSelectedRange=x=>{const d=String(x?.date||x?.createdAt||'').slice(0,10);return d&&d>=rangeFrom&&d<=rangeTo};
 const rangeSales=(state.sales||[]).filter(inSelectedRange),rangePurchases=(state.purchases||[]).filter(inSelectedRange),rangeSaleDetails=rangeSales.map(x=>saleDetail(x));
 const sales=rangeSaleDetails.reduce((n,x)=>n+Number(x.net||0),0),posCogs=rangeSaleDetails.reduce((n,x)=>n+Number(x.cost||0),0),grossProfit=sales-posCogs,grossMargin=sales?grossProfit/sales*100:0;
 const rangeDre=(state.dreRecords||[]).filter(inSelectedRange),dreExpenses=rangeDre.filter(x=>x.type==='expense'),dreIncome=rangeDre.filter(x=>x.type==='income'),expenseTotal=dreExpenses.reduce((n,x)=>n+Number(x.amount||0),0),incomeTotal=dreIncome.reduce((n,x)=>n+Number(x.amount||0),0),operatingResult=grossProfit-expenseTotal+incomeTotal;
