 const rangePurchaseIds=new Set(rangePurchases.map(x=>String(x.purchaseId||x.id||''))),unpaid=purchaseGroupRows().filter(x=>rangePurchaseIds.has(String(x.id))&&['PENDIENTE','PARCIAL'].includes(purchaseStatus(x))).reduce((n,x)=>n+purchaseBalance(x),0);
 const expenseByCategory=new Map();dreExpenses.forEach(x=>{const category=String(x.category||'Sin categoría').trim()||'Sin categoría';expenseByCategory.set(category,(expenseByCategory.get(category)||0)+Number(x.amount||0))});const topOperatingExpenses=[...expenseByCategory.entries()].sort((a,b)=>b[1]-a[1]).slice(0,5),maxOperatingExpense=Math.max(1,...topOperatingExpenses.map(x=>x[1]));
 const user=currentUser();
 const todayKey=new Date().toISOString().slice(0,10);
 const todaySales=(state.sales||[]).filter(x=>String(x.date||x.createdAt||'').slice(0,10)===todayKey).reduce((n,x)=>n+Number(saleDetail(x).net||0),0);
 const topMap=rangeSales.reduce((m,x)=>{const k=x.product||x.recipe||'Sin producto';m[k]=(m[k]||0)+Number(saleDetail(x).net||0);return m},{});
 const topRows=Object.entries(topMap).sort((a,b)=>b[1]-a[1]).slice(0,5);
 const months=['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
 const monthly=Array.from({length:12},(_,i)=>{let sales=0,cost=0;for(const x of rangeSales){const d=new Date(x.date||x.createdAt||'');if(d.getMonth()===i){sales+=Number(saleDetail(x).net||0);cost+=Number(x.cost||0)}}return {sales,cost}});
 const salesPeriod=['month','quarter','year'].includes(state._dashboardSalesPeriod)?state._dashboardSalesPeriod:'month',salesRangeEnd=new Date(rangeTo+'T12:00:00'),salesStart=new Date(rangeFrom+'T12:00:00'),salesCursor=new Date(salesStart.getFullYear(),salesStart.getMonth(),1);
 if(salesPeriod==='quarter')salesCursor.setMonth(Math.floor(salesCursor.getMonth()/3)*3);else if(salesPeriod==='year')salesCursor.setMonth(0);
 const salesPeriods=[];while(salesCursor<=salesRangeEnd&&salesPeriods.length<120){const periodStart=new Date(salesCursor),periodEnd=new Date(salesCursor);periodEnd.setMonth(periodEnd.getMonth()+(salesPeriod==='month'?1:salesPeriod==='quarter'?3:12));periodEnd.setDate(periodEnd.getDate()-1);const from=periodStart<salesStart?rangeFrom:periodStart.toISOString().slice(0,10),to=periodEnd>salesRangeEnd?rangeTo:periodEnd.toISOString().slice(0,10);let periodSales=0,periodCost=0;for(const x of rangeSales){const d=String(x.date||x.createdAt||'').slice(0,10);if(d>=from&&d<=to){periodSales+=Number(saleDetail(x).net||0);periodCost+=Number(x.cost||0)}}const year=periodStart.getFullYear(),month=periodStart.getMonth(),label=salesPeriod==='year'?String(year):salesPeriod==='quarter'?`T${Math.floor(month/3)+1} ${String(year).slice(-2)}`:salesPeriods.length>11?`${months[month]} ${String(year).slice(-2)}`:months[month];salesPeriods.push({label,sales:periodSales,cost:periodCost});salesCursor.setMonth(salesCursor.getMonth()+(salesPeriod==='month'?1:salesPeriod==='quarter'?3:12))}
 const salesChartMax=Math.max(1,...salesPeriods.flatMap(x=>[x.sales,x.cost])),salesChart=`<div class="monthly-chart" style="grid-template-columns:repeat(${Math.max(1,salesPeriods.length)},minmax(18px,1fr))">${salesPeriods.map(x=>`<div class="month-col"><div class="month-bars"><span class="bar sales-bar" title="Ventas ${money(x.sales)}" style="height:${Math.max(2,(x.sales/salesChartMax)*100)}%"></span><span class="bar cost-bar" title="Costos ${money(x.cost)}" style="height:${Math.max(2,(x.cost/salesChartMax)*100)}%"></span></div><small>${esc(x.label)}</small></div>`).join('')}</div>`;
 const dreMonthly=Array.from({length:12},(_,i)=>{let income=0,expense=0;for(const x of state.dreRecords||[]){if(!inSelectedRange(x))continue;const d=new Date(String(x.date||'').slice(0,10)+'T12:00:00');if(d.getMonth()!==i)continue;const amount=Number(x.amount||0);if(x.type==='income')income+=amount;else if(x.type==='expense')expense+=amount}return{income,expense}});
 const trendMetric=['net','sales','expenses'].includes(state._dashboardTrendMetric)?state._dashboardTrendMetric:'net',trendValues=monthly.map((x,i)=>trendMetric==='sales'?x.sales:trendMetric==='expenses'?dreMonthly[i].expense:x.sales-x.cost+dreMonthly[i].income-dreMonthly[i].expense),trendMin=Math.min(0,...trendValues),trendMax=Math.max(0,...trendValues),trendSpan=trendMax-trendMin||1,trendY=v=>205-((v-trendMin)/trendSpan)*170,trendX=i=>36+i*(1128/11),trendLine=trendValues.map((v,i)=>`${trendX(i)},${trendY(v)}`).join(' '),trendColor=trendMetric==='expenses'?'#ef8a16':trendMetric==='sales'?'#22a06b':'#e73535',trendLabel={net:'Resultado neto',sales:'Ventas netas',expenses:'Gastos DRE'}[trendMetric];
