function parseRecipeImportText(text){
 const raw=String(text||'').replace(/\r/g,'').split('\n').map(x=>x.replace(/\s+/g,' ').trim()).filter(Boolean);
 const units='fl\\s*oz|fluid\\s*ounces?|oz|ounces?|lb|lbs|pounds?|kg|kgs?|kilograms?|g|grams?|ml|millilit(?:er|re)s?|l|lt|lit(?:er|re)s?|tsp|teaspoons?|tbsp|tablespoons?|cups?|units?|ea|each|pieces?|pcs?|qt|quarts?|gal|gallons?|pt|pints?';
 const number='(?:\\d+(?:[.,]\\d+)?(?:\\s+\\d+\\/\\d+)?|\\d+\\/\\d+|[¼½¾⅓⅔⅛⅜⅝⅞])';
 const quantityPattern=/^\s*((?:\d+(?:[.,]\d+)?(?:\s+\d+\/\d+)?|\d+\/\d+|[¼½¾⅓⅔⅛⅜⅝⅞])(?:\s*[-–—]\s*(?:\d+(?:[.,]\d+)?(?:\s+\d+\/\d+)?|\d+\/\d+|[¼½¾⅓⅔⅛⅜⅝⅞]))?)\s*(fl\s*oz|fluid\s*ounces?|oz|ounces?|lb|lbs|pounds?|kg|kgs?|kilograms?|g|grams?|ml|millilit(?:er|re)s?|l|lt|lit(?:er|re)s?|tsp|teaspoons?|tbsp|tablespoons?|cups?|units?|ea|each|pieces?|pcs?|qt|quarts?|gal|gallons?|pt|pints?)\s*$/i;
 const fractionChars={'¼':.25,'½':.5,'¾':.75,'⅓':1/3,'⅔':2/3,'⅛':.125,'⅜':.375,'⅝':.625,'⅞':.875};
 const amountValue=value=>{const t=String(value||'').trim().replace(',','.');if(fractionChars[t]!=null)return fractionChars[t];const mixed=t.match(/^(\d+)\s+(\d+)\/(\d+)$/);if(mixed)return Number(mixed[1])+Number(mixed[2])/Number(mixed[3]);const fraction=t.match(/^(\d+)\/(\d+)$/);if(fraction)return Number(fraction[1])/Number(fraction[2]);return Number(t)};
 const parseQuantity=line=>{const match=String(line||'').match(quantityPattern);if(!match)return null;const parts=match[1].split(/\s*[-–—]\s*/),values=parts.map(amountValue);if(!values.every(v=>Number.isFinite(v)&&v>0))return null;return {qty:values.length===2?(values[0]+values[1])/2:values[0],unit:normalizeRecipeUnit(match[2]),range:values.length===2?`${match[1]} ${match[2]}`:''}};
 const titleLine=raw.find(line=>/^(?:receta\s+est[aá]ndar|standard\s+recipe)\s*[-:]/i.test(line));
 let name=titleLine?titleLine.replace(/^(?:receta\s+est[aá]ndar|standard\s+recipe)\s*[-:]\s*/i,'').trim():'';
 if(name){const titleIndex=raw.indexOf(titleLine),alias=raw[titleIndex+1]||'';if(/^\([^)]{2,60}\)$/.test(alias))name+=` ${alias}`}
 if(!name){for(const line of raw.slice(0,12)){const candidate=line.replace(/^[#\-•*\d.\s]+/,'').trim();if(candidate&&candidate.length>2&&!/^(?:ingredientes?|ingredients?|categor[ií]a|category|ingredient|cantidad|quantity|notas?|notes?|rendimiento|yield|procedimiento|preparation|preparaci[oó]n)$/i.test(candidate)&&!/^\(?[aá]rea\)?$/i.test(candidate)){name=candidate;break}}}
 const items=[],seen=new Set(),rangeNotes=[];
 const add=(product,qty,unit,range='')=>{product=String(product||'').replace(/^[#\-•*]+/,'').trim();unit=String(unit||'unidad').trim();qty=Number(qty);if(!product||!(qty>0))return;const key=product.toLowerCase()+'|'+qty+'|'+unit.toLowerCase();if(seen.has(key))return;seen.add(key);items.push({product,qty,unit});if(range)rangeNotes.push(`${product}: ${range}`)};
 const headers=raw.map((line,index)=>/^(categor[ií]a|category)$/i.test(line)?index:-1).filter(i=>i>=0);
 if(headers.length){const start=headers[0]+1,methodIndex=raw.findIndex(line=>/^(procedimiento|procedure|preparaci[oó]n|preparation|method|m[eé]todo)\b/i.test(line)),end=methodIndex>=0?methodIndex:raw.length;for(let i=start+2;i<end;i++){const quantity=parseQuantity(raw[i]);if(quantity){const ingredient=raw[i-1];if(!/^(cantidad|quantity|notas?|notes?)$/i.test(ingredient))add(ingredient,quantity.qty,quantity.unit,quantity.range)}}}
 const ingredientPattern=new RegExp('^(.+?)\\s+('+number+')\\s*('+units+')\\s*$','i'),reversedPattern=new RegExp('^('+number+')\\s*('+units+')\\s+(.+)$','i'),labelPattern=new RegExp('^(.+?)\\s*[:\\-]\\s*('+number+'(?:\\s*[-–—]\\s*'+number+')?)\\s*('+units+')\\b','i');
 for(const line of raw){if(/^(?:categor[ií]a|category|ingrediente|ingredient|cantidad|quantity|notas?|notes?|ingredientes?|components?)$/i.test(line))continue;let match=line.match(ingredientPattern);if(match){add(match[1],amountValue(match[2]),normalizeRecipeUnit(match[3]));continue}match=line.match(reversedPattern);if(match){add(match[3],amountValue(match[1]),normalizeRecipeUnit(match[2]));continue}match=line.match(labelPattern);if(match){const q=parseQuantity(`${match[2]} ${match[3]}`);if(q)add(match[1],q.qty,q.unit,q.range)}}
 let yieldQty=1,yieldUnit='orden',portions=0;
 for(const line of raw){let m=line.match(/(?:yield|rendimiento)\s*[:\-]?\s*(\d+(?:[.,]\d+)?)\s*porciones?\s*(?:de\s*)?(\d+(?:[.,]\d+)?)\s*(fl\s*oz|oz|lb|kg|g|ml|l)\b/i);if(m){portions=Number(m[1].replace(',','.'));yieldQty=portions*Number(m[2].replace(',','.'));yieldUnit=normalizeRecipeUnit(m[3]);const total=line.match(/\((\d+(?:[.,]\d+)?)\s*(fl\s*oz|oz|lb|kg|g|ml|l)\s+total\)/i);if(total){yieldQty=Number(total[1].replace(',','.'));yieldUnit=normalizeRecipeUnit(total[2])}break}m=line.match(new RegExp('(?:yield|rendimiento)\\s*[:\\-]?\\s*(\\d+(?:[.,]\\d+)?)\\s*('+units+')?','i'));if(m){yieldQty=Number(m[1].replace(',','.'));yieldUnit=m[2]?normalizeRecipeUnit(m[2]):'orden'}const portionMatch=line.match(/(?:porciones|servings?)\s*[:\-]?\s*(\d+)/i);if(portionMatch)portions=Number(portionMatch[1])}
 const methodStart=raw.findIndex(line=>/^(procedure|procedimiento|method|m[eé]todo|preparation|preparaci[oó]n|instructions?|instrucciones)\b/i.test(line));
 const notesStart=raw.findIndex((line,index)=>index>methodStart&&/^(notes?|notas?)\b/i.test(line));
 const method=methodStart>=0?raw.slice(methodStart+1,notesStart>methodStart?notesStart:Math.min(raw.length,methodStart+15)).join('\n'):'';
 const notes=[notesStart>=0?raw.slice(notesStart+1,notesStart+5).join('\n'):'',rangeNotes.length?`Cantidades en rango (valor medio importado; revisar): ${rangeNotes.join('; ')}`:''].filter(Boolean).join('\n');
 return {name:name||'Receta importada',productType:'Producto Final',area:'Cocina',category:'Cocina',yieldQty,yieldUnit,portions,items,method,plating:'',notes};
}
async function recipeImportAction(target='final'){const input=document.createElement('input');input.type='file';input.accept='image/*,application/pdf,.txt,.csv,.xlsx,.xls';input.style.display='none';document.body.appendChild(input);input.onchange=async()=>{const file=input.files?.[0];input.remove();if(!file)return;modal(`<h3>Procesando receta</h3><p class="muted">${esc(file.name)}</p><div class="resultbox">Extrayendo texto. Los PDF escaneados se convierten página por página a imagen y pasan por OCR.</div>`);try{const r=await readRecipeImportFile(file),p=parseRecipeImportText(r.text);p.rawText=r.text;p.productType=target==='prep'?'Pre-elaborado':target==='barRecipe'||target==='barPrep'?'Producto para Bar':'Producto Final';recipeImportReviewModal(target,file,p)}catch(e){console.error('LRX recipe import',e);modal(`<h3>No se pudo procesar el archivo</h3><p>${esc(e?.message||e)}</p><div class="resultbox">No se inventaron datos. Prueba con JPG/PNG o un PDF con mejor resolución.</div><div class="actions"><button class="btn" data-action="close">Cerrar</button></div>`)}};input.click()}
function recipeYieldUnits(current=''){
 const builtins=['unidad','oz','lb','kg','g','mL','L','gal','qt','pt','tsp','tbsp','cup'];
 const custom=(state.masterUnits||[]).map(u=>String(u.symbol||u.name||'').trim()).filter(Boolean);
 return [...new Set([...builtins,...custom,String(current||'').trim()].filter(Boolean))];
}
function createRecipeYieldUnit(selectId='ru'){
 const name=prompt('Nombre de la nueva unidad de rendimiento (ej. bandeja, jarra, porción):');
 if(!name?.trim())return;
 const symbol=prompt('Símbolo de la unidad (ej. bdj, jra, porción):',name.trim());
 if(!symbol?.trim())return;
 const dup=(state.masterUnits||[]).find(u=>normMaster(u.name)===normMaster(name)||normMaster(u.symbol)===normMaster(symbol));
 if(dup){const el=document.getElementById(selectId);if(el){el.value=dup.symbol||dup.name;}return toast('La unidad ya existe y fue seleccionada.');}
 const snapshot=JSON.stringify(state);state.masterUnits=[...(state.masterUnits||[]),{id:'UNIT-'+Date.now(),name:name.trim(),symbol:symbol.trim(),type:'Unidad',baseUnit:symbol.trim(),factor:1,source:'RECETA',createdAt:now(),updatedAt:now()}];audit('UNIDAD_RENDIMIENTO_CREADA',`${name.trim()} (${symbol.trim()})`);if(!save()){restoreStateSnapshot(snapshot);return}
 const el=document.getElementById(selectId);if(el){el.innerHTML=recipeYieldUnits(symbol).map(u=>`<option value="${esc(u)}">${esc(u)}</option>`).join('')+'<option value="__custom">＋ Crear unidad</option>';el.value=symbol.trim();}
 toast('Unidad de rendimiento creada y guardada');
}
