function inventory208ImportModal(){modal(`<h3>Importar inventario</h3><p class="muted">Admite CSV y XLSX. El sistema muestra una vista previa y solo guarda cuando confirmas.</p><input id="invImportFile" type="file" accept=".csv,.xlsx,.xls"><div id="invImportPreview" class="card" style="margin-top:12px"><span class="muted">Selecciona un archivo.</span></div><div class="actions"><button class="btn" data-action="close">Cancelar</button><button class="btn primary" id="invImportSave" disabled>Importar registros</button></div>`);document.getElementById('invImportFile').onchange=e=>previewInventoryImport(e.target.files?.[0]);}
async function previewInventoryImport(file){if(!file)return;try{let rows=[];if(/\.csv$/i.test(file.name)){const text=await file.text();rows=parseCSV208(text)}else if(window.XLSX){const buf=await file.arrayBuffer(),wb=XLSX.read(buf,{type:'array'});const ws=wb.Sheets[wb.SheetNames[0]];rows=XLSX.utils.sheet_to_json(ws,{defval:''})}else throw new Error('El lector XLSX no está disponible; usa CSV o conecta a Internet para cargar SheetJS.');window._lrxInvImportRows=rows.slice(0,5000);const cols=[...new Set(rows.flatMap(x=>Object.keys(x)))];document.getElementById('invImportPreview').innerHTML=`<b>${rows.length}</b> registros detectados · columnas: ${esc(cols.join(', '))}<div class="tablewrap"><table><thead><tr>${cols.slice(0,10).map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,8).map(r=>`<tr>${cols.slice(0,10).map(c=>`<td>${esc(r[c])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;const b=document.getElementById('invImportSave');b.disabled=!rows.length;b.onclick=()=>saveInventoryImport();}catch(e){document.getElementById('invImportPreview').innerHTML=`<span class="status">Error: ${esc(e.message||e)}</span>`}}
function parseCSV208(text){const lines=text.split(/\r?\n/).filter(x=>x.trim());if(!lines.length)return [];const parse=line=>{const out=[];let cur='',q=false;for(let i=0;i<line.length;i++){const ch=line[i];if(ch==='"'&&line[i+1]==='"'){cur+='"';i++;continue}if(ch==='"'){q=!q;continue}if((ch===','||ch===';')&&!q){out.push(cur);cur=''}else cur+=ch}out.push(cur);return out};const h=parse(lines[0]);return lines.slice(1).map(l=>{const a=parse(l),o={};h.forEach((k,i)=>o[k]=a[i]??'');return o})}
function saveInventoryImport(){const rows=Array.isArray(window._lrxInvImportRows)?window._lrxInvImportRows:[];const snapshot=JSON.stringify(state);let ok=0,skip=0;for(const r of rows){const find=k=>{const key=Object.keys(r).find(x=>String(x).trim().toLowerCase()===k);return key?r[key]:''};const name=String(find('producto')||find('product')||find('nombre')||'').trim();const qty=Number(find('cantidad')||find('qty')||find('existencia')||0);if(!name||!Number.isFinite(qty)||qty<=0){skip++;continue}const p=inv208Products().find(x=>String(x.name).toLowerCase()===name.toLowerCase()||String(x.id||'').toLowerCase()===String(find('codigo')||find('sku')||'').toLowerCase());if(!p){skip++;continue}const unit=String(find('unidad')||p.standardUnit||p.unit||'unidad'),loc=String(find('ubicacion')||find('location')||'Almacén'),costRaw=find('costo')||find('cost')||p.finalCost||p.cost||0,cost=Number(costRaw),lot=String(find('lote')||find('lot')||''),expiry=String(find('vencimiento')||find('expiry')||''),validDate=d=>/^\d{4}-\d{2}-\d{2}$/.test(d)&&!Number.isNaN(Date.parse(d))&&new Date(d+'T00:00:00').toISOString().slice(0,10)===d;if(!Number.isFinite(cost)||cost<0||(expiry&&!validDate(expiry))){skip++;continue}const target=state.inventory.find(x=>String(x.productId||'')===String(p.id||'')&&String(x.unit||'').toLowerCase()===unit.toLowerCase()&&String(x.location||'Almacén')===loc);if(target){const before=Number(target.qty||0);const after=before+qty;target.unitCost=after>0?(before*Number(target.unitCost||cost)+qty*cost)/after:cost;target.qty=after}else state.inventory.push({id:'INV-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),productId:p.id||'',product:p.name,unit,qty,unitCost:cost,location:loc,lot,expiryDate:expiry});if(lot||expiry)state.inventoryLots=[{id:'LOT-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),productId:p.id||'',product:p.name,qty,unit,unitCost:cost,location:loc,lot,expiryDate:expiry,receivedDate:now().slice(0,10),source:'IMPORT'},...inv208Lots()];state.movements.push({id:'MOV-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),date:now(),type:'IMPORTACIÓN INVENTARIO',product:p.name,productId:p.id||'',qty,unit,unitCost:cost,total:qty*cost,location:loc,lot,expiryDate:expiry,ref:'IMPORT-'+Date.now()});ok++}if(!ok){toast(`No se importó ningún registro: ${skip} fila(s) necesitan corrección`);return}audit('INVENTORY_IMPORT',`${ok} registros importados · ${skip} omitidos`);if(!save()){restoreStateSnapshot(snapshot);return}window._lrxInvImportRows=null;close();render();toast(`Importación completada: ${ok} registros · ${skip} omitidos`)}


