function shoppingList(){const rows=localSearch(state.shopping||[],'_shoppingQ'),low=(state.inventory||[]).filter(x=>Number(x.minQty||0)>0&&Number(x.qty||0)<=Number(x.minQty||0));return head('Lista de Compras','Productos pendientes para reabastecer; registrar aquí no cambia el inventario.',`<button class="btn primary" data-action="shopping-new">＋ Agregar producto</button> <button class="btn" data-action="shopping-from-low">＋ Añadir faltantes de inventario (${low.length})</button> <button class="btn" data-action="shopping-export">Excel + CSV</button> <button class="btn" data-action="shopping-print">Imprimir / PDF</button>`)+`<div class="grid"><div class="card kpi"><small>Pendientes</small><strong>${rows.filter(x=>!x.done).length}</strong></div><div class="card kpi"><small>Listos / comprados</small><strong>${rows.filter(x=>x.done).length}</strong></div></div><div class="card" style="margin-top:14px"><div class="toolbar"><input id="shoppingQ" class="input search" value="${esc(state._shoppingQ||'')}" placeholder="Buscar producto o proveedor"></div>${rowsTable([['Producto'],['Cantidad'],['Proveedor'],['Prioridad'],['Estado']],rows.slice().reverse().map(x=>`<tr><td><b>${esc(x.product||x.name)}</b><small>${esc(x.notes||'')}</small></td><td>${esc(x.qty||'—')} ${esc(x.unit||'')}</td><td>${esc(x.supplier||'—')}</td><td>${esc(x.priority||'Normal')}</td><td><span class="status">${x.done?'COMPRADO':'PENDIENTE'}</span></td><td><button class="btn" data-action="shopping-toggle" data-id="${esc(x.id)}">${x.done?'Reabrir':'Marcar comprado'}</button> <button class="btn" data-action="shopping-edit" data-id="${esc(x.id)}">Editar</button> <button class="btn danger" data-action="shopping-delete" data-id="${esc(x.id)}">Eliminar</button></td></tr>`).join(''),'No hay productos en la lista.')}</div>`}
