  if(!name)return toast('Indica el nombre');if(!Number.isFinite(yieldQty)||yieldQty<=0||!Number.isFinite(salePrice)||salePrice<0)return toast('Revisa el rendimiento y el precio.');
  const rows=[...document.querySelectorAll('.bar-ing')],items=[];for(const row of rows){const itemName=row.querySelector('.bi-name')?.value.trim()||'',qty=Number(row.querySelector('.bi-qty')?.value||0),unit=row.querySelector('.bi-unit')?.value||'unidad',manualCost=Number(row.querySelector('.bi-cost')?.value||0);if(!itemName&&!qty)continue;if(!itemName||!Number.isFinite(qty)||qty<=0||!Number.isFinite(manualCost)||manualCost<0)return toast('Revisa cada insumo, cantidad y costo.');const prod=effectiveMaster('products').find(p=>String(p.id)===String(row.dataset.productId))||effectiveMaster('products').find(p=>String(p.name).trim().toLowerCase()===itemName.toLowerCase())||state.products.find(p=>String(p.name).trim().toLowerCase()===itemName.toLowerCase()),prep=effectiveMaster('preps').find(x=>String(x.id)===String(row.dataset.prepId))||effectiveMaster('preps').find(x=>String(x.name).trim().toLowerCase()===itemName.toLowerCase());items.push({name:itemName,product:itemName,productId:prod?.id||'',prepId:prep?.id||'',qty,unit,cost:manualCost})}
  const cost=items.reduce((sum,x)=>{const p=effectiveMaster('products').find(y=>String(y.id)===String(x.productId))||state.products.find(y=>String(y.id)===String(x.productId));return sum+(p?LRXCost.lineCost(p,x.qty,x.unit):x.cost*x.qty)},0),attachments=window._lrxRecipeAttachments||[],documents=[];
